mapper.select:
select c.chat_content_id as chatContentId, c.chat_conversation_id as chatConversationId,c.voice_length as voiceLength, c.user_id as userId,u.user_name as userName,u.avatar,c.content,c.message_type as messageType, c.create_time as createTime,c.width,c.height,c.good_id as goodId,u.phone as phone from chat_content c left join tb_user u on u.user_id=c.user_id where 1=1
and c.chat_conversation_id=#{chatConversationId}
and c.content like CONCAT('%',#{content},'%')
and c.is_delete is null
and u.phone like CONCAT('%',#{phone},'%')
and c.create_time >= #{startTime}
and c.create_time <= #{endTime}
and u.user_name like CONCAT('%',#{userName},'%')
order by c.create_time desc
